const uint16_t color_table[8]={BLACK,BULE,GREEN,CYAN,RED,PURPLE,YELLOW,WHITE};
//解压缩游程编码数据，返回填充完毕后的下一位地址
uint16_t *end_p(uint8_t compressed_data,uint16_t *target){
    uint8_t quantity = compressed_data>>3;//高5位为有几个像素
    uint16_t color=color_table[compressed_data&0x07];//低3位为像素颜色
    for(uint8_t i = 0; i != quantity; i++)
    {
        *target = color;
        target++;
    }
    return target;
} 
//返回解压后的数据，bit0~bit15是颜色数据，bit16~bit23是数量
uint32_t jy(uint8_t compressed_data){
    uint16_t c = color_table[(compressed_data & 0x7)];
    uint8_t q = (compressed_data>>3)+1;
    return c+(q<<16);
}
//在当前位置绘制压缩后的图片，需要注意图片的长宽
void draw(const uint8_t *s,uint16_t size){
    uint16_t color=0;uint8_t q =0;
    while ((size) || (q!=0) ) {
		if (q==0) {//说明发送完毕
			q = jy(*s) >> 16;
			color = jy(*s) & 0xFFFF;//用于存储颜色
			s++;
            size--;
		}
		q--;
		SPI1_WriteWord(color);
	}
}